// The lint check for CONTRIBUTING.md's "Rules for Worker code". It uses
// typescript-eslint's rules that read type information, because whether a call
// returns a promise (a D1 statement's `run()`, `fetch()`) is known only from
// the types. Each workspace's own tsconfig.json supplies those types.
import tseslint from 'typescript-eslint';

export default [
  {
    ignores: [
      '**/dist/',
      '**/.wrangler/',
      // Tooling configuration, not code that the Worker or the app runs.
      '**/*.config.ts',
      // Generated by `wrangler types`.
      'workers/api/worker-configuration.d.ts',
      // Code that breaks the rules on purpose; tools/lint's tests lint it.
      'tools/lint/fixtures/',
      // Agent worktrees are full checkouts of this repository.
      '.claude/',
    ],
  },
  {
    files: ['**/*.{ts,tsx}'],
    languageOptions: {
      parser: tseslint.parser,
      parserOptions: { projectService: true, tsconfigRootDir: import.meta.dirname },
    },
    plugins: { '@typescript-eslint': tseslint.plugin },
    rules: {
      '@typescript-eslint/no-floating-promises': [
        'error',
        {
          // The node:test runner collects the tests that a file declares at
          // its top level, and reports their failures itself.
          allowForKnownSafeCalls: [
            { from: 'package', package: 'node:test', name: ['test', 'it', 'describe', 'suite'] },
          ],
        },
      ],
      '@typescript-eslint/no-misused-promises': [
        'error',
        // An async event handler in JSX (`onClick={async () => ...}`) is routine
        // in the web app, and the browser reports its rejection.
        { checksVoidReturn: { attributes: false } },
      ],
    },
  },
];
